#!/usr/bin/env python3
"""Render the tested-combinations table in docs/user-guide/tools.md from smoke-matrix.json.

Usage: tested_combinations.py [--check]

Without arguments, rewrites the table in place. With --check, exits non-zero if
the table is out of date (run in CI so the docs can't drift from the matrix).
"""

import json
import shlex
import sys
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
MATRIX_FILE = ROOT / ".github" / "smoke-matrix.json"
DOC_FILE = ROOT / "docs" / "user-guide" / "tools.md"
START = "<!-- tested-combinations:start (generated by .github/scripts/tested_combinations.py) -->"
END = "<!-- tested-combinations:end -->"


def tool_names():
    names = {}
    for path in (ROOT / "registry" / "tools").glob("*.toml"):
        tool = tomllib.loads(path.read_text())["tool"]
        names[tool["id"]] = tool["name"]
    return names


def combination(flags, names):
    """A readable label for a row's flags, e.g. "Aiken + MeshJS"."""
    args = shlex.split(flags)
    roles = {}
    for flag, value in zip(args, args[1:]):
        if flag in ("--on-chain", "--off-chain", "--fullstack"):
            roles[flag] = names[value]
    if "--fullstack" in roles:
        label = f"{roles['--fullstack']} (fullstack)"
    else:
        parts = [roles[f] for f in ("--on-chain", "--off-chain") if f in roles]
        label = " + ".join(parts)
        if len(parts) == 1:
            label += " (on-chain only)" if "--on-chain" in roles else " (off-chain only)"
    if "--nix" in args:
        label += ", with `--nix`"
    return label


def render(matrix, names):
    rows = {}
    for section in ("smoke", "devnet"):
        for row in matrix.get(section, []):
            rows.setdefault(combination(row["flags"], names), set()).add(section)
    lines = [
        "| Combination | Builds and passes its tests | Runs end to end on Yaci DevKit |",
        "|-------------|:---------------------------:|:------------------------------:|",
    ]
    # Single tools first, then pairs, then fullstack; alphabetical within each.
    def order(label):
        kind = 2 if "(fullstack)" in label else 0 if "only)" in label else 1
        return (kind, label)

    for label in sorted(rows, key=order):
        # A devnet row runs the project's `just test` too, so it also covers build and test.
        devnet = "✅" if "devnet" in rows[label] else ""
        lines.append(f"| {label} | ✅ | {devnet} |")
    return "\n".join(lines)


def main():
    matrix = json.loads(MATRIX_FILE.read_text())
    doc = DOC_FILE.read_text()
    try:
        head, rest = doc.split(START, 1)
        _, tail = rest.split(END, 1)
    except ValueError:
        sys.exit(f"{DOC_FILE.relative_to(ROOT)}: missing tested-combinations markers")
    updated = f"{head}{START}\n{render(matrix, tool_names())}\n{END}{tail}"
    if "--check" in sys.argv[1:]:
        if updated != doc:
            sys.exit(
                f"{DOC_FILE.relative_to(ROOT)} is out of date with smoke-matrix.json; "
                "run .github/scripts/tested_combinations.py"
            )
        return
    DOC_FILE.write_text(updated)


if __name__ == "__main__":
    main()
